helper:
ywc_shu_pay_military_advance_once = {
	if = {
		limit = {
			net_fixed_income >= 0
			NOT = { has_variable = ywc_shu_military_advance_paid }
		}
		ywc_shu_capture_cost_base = yes
		add_treasury = { value = var:ywc_shu_fiscal_cost multiply = -0.25 }
		set_variable = { name = ywc_shu_military_advance_paid value = 1 }
		set_variable = { name = ywc_shu_military_payer value = 1 }
	}
}

option_effect:
{
ywc_shu_pay_military_advance_once = yes
set_variable = { name = ywc_shu_pending_event value = 1004 }
}
